'use strict';
(() => {
const D=window.MODEL_DATA, $=s=>document.querySelector(s), models=D.models, source=D.sources;
const labels={coverage:['覆盖检查 / 待核验','找到遗漏，逐项补齐。','对照官方发布账号与框架目录，公开仍待核验的模型和变体。'],framework:['框架支持索引','先找到模型，再核对支持。','汇总 SGLang cookbook 与 vLLM 官方支持表，保留具体版本和证据边界。'],catalog:['模型目录','查参数，也查出处。','从架构到推理细节，把常用大模型放在同一张桌上。'],compare:['模型对比','把差异，放在一起看。','最多并排比较 4 款模型，每个字段保留官方出处。'],sources:['官方来源','资料有出处，结论有边界。','从模型卡、官方配置与技术报告，回到信息的原点。'],guide:['字段与口径','读懂数字背后的口径。','先知道参数在说什么，再决定模型是否适合你的部署。']};
const normalize=v=>String(v??'').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const coverageState={q:new URLSearchParams(location.search).get('q')||'',publisher:'',status:'pending',type:'',origin:''};let coveragePage=1;
const queueLabels={model_candidate:'模型候选',variant_hint:'量化 / 精度名称提示',draft_hint:'草稿 / 辅助模块名称提示',base_preview_hint:'Base / Preview 名称提示'};
function coverageMatches(){return D.coverage.entries.filter(x=>(!coverageState.q||normalize([x.name,x.repo,x.publisher].join(' ')).includes(normalize(coverageState.q)))&&(!coverageState.publisher||x.publisher===coverageState.publisher)&&(!coverageState.status||(coverageState.status==='ready'?!!x.modelId:!x.modelId))&&(!coverageState.type||x.queueType===coverageState.type)&&(!coverageState.origin||x.origin===coverageState.origin));}
function renderCoverage(){
 if(!$('#coverage-search')){
  const c=D.coverage,pending=c.entries.filter(x=>!x.modelId).length,incomplete=c.inventories.filter(x=>!x.complete);
  $('#coverage-view').innerHTML='<section class="stats framework-stats"><div><span>已核验参数档案</span><strong>'+models.length+'</strong><small>每个事实独立记录官方证据</small></div><div><span>待核验模型 / 变体</span><strong>'+pending+'</strong><small>包含历史版本、量化、草稿与目录引用</small></div><div><span>对照官方发布账号</span><strong>'+c.inventories.length+'</strong><small>分页遍历 · 不设创建日期门槛</small></div></section><div class="research-note"><span class="note-mark">i</span><p><strong>目录发现不等于参数已核验。</strong> 对照已核实发布账号的公开仓库（文本生成、多模态生成标签）与现有框架索引；框架引用可能含第三方仓库或占位条目。分类仅按名称辅助整理，待审条目不能用于参数比较。未覆盖其他发布账号、缺少相应标签的仓库和全部 API 服务。<br>目录检查 '+esc(c.checkedAt)+' · '+(incomplete.length?'未完整读取账号：'+incomplete.map(x=>esc(x.publisher)).join('、'):'所列账号均已遍历全部返回页')+'；目录检查时间不改变事实核验日期。<br><a href="coverage-audit.csv" download>↓ 下载完整对照 CSV</a></p></div><section class="catalog-panel"><div class="search-row"><label class="search"><span>⌕</span><input id="coverage-search" type="search" aria-label="搜索覆盖检查" placeholder="搜索遗漏模型、仓库或发布账号…"></label></div><div class="filters"><label>发布账号 <select id="coverage-publisher"><option value="">全部账号</option>'+[...new Set(c.entries.map(x=>x.publisher))].sort().map(x=>'<option>'+esc(x)+'</option>').join('')+'</select></label><label>建档情况 <select id="coverage-status"><option value="pending">待核验</option><option value="ready">已建档</option><option value="">全部条目</option></select></label><label>名称分类 <select id="coverage-type"><option value="">全部分类</option>'+Object.entries(queueLabels).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></label><label>发现途径 <select id="coverage-origin"><option value="">全部途径</option><option value="author_inventory">发布账号仓库目录</option><option value="framework_reference">仅框架引用</option><option value="curated">已有参数档案</option></select></label><span id="coverage-count"></span></div><div class="table-scroll" tabindex="0" aria-label="模型覆盖检查，可横向滚动"><table class="index-table"><thead><tr><th>模型 / 变体</th><th>发布账号</th><th>发现证据</th><th>待审分类</th><th>参数档案</th></tr></thead><tbody id="coverage-rows"></tbody></table></div><div class="table-footer"><span id="coverage-summary"></span><div><button class="text-button" id="coverage-prev">← 上一页</button><button class="text-button" id="coverage-next">下一页 →</button></div></div></section>';
  $('#coverage-search').addEventListener('input',e=>{coverageState.q=e.target.value;coveragePage=1;renderCoverageRows();});
  for(const k of ['publisher','status','type','origin'])$('#coverage-'+k).addEventListener('change',e=>{coverageState[k]=e.target.value;coveragePage=1;renderCoverageRows();});
 }
 $('#coverage-search').value=coverageState.q;coveragePage=1;renderCoverageRows();
}
function renderCoverageRows(){
 const rows=coverageMatches(),pages=Math.max(1,Math.ceil(rows.length/50));coveragePage=Math.min(pages,Math.max(1,coveragePage));
 $('#coverage-count').textContent=rows.length+' 个条目';
 $('#coverage-rows').innerHTML=rows.slice((coveragePage-1)*50,coveragePage*50).map(x=>'<tr><td><a class="model-name" href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">'+esc(x.name)+' ↗</a><small class="index-repo">'+esc(x.repo||'未指定仓库')+'</small></td><td>'+esc(x.publisher)+'</td><td>'+(x.origin==='author_inventory'?'已遍历发布账号仓库'+(x.inventoryStale?'（上次目录，本次读取失败）':''):x.origin==='curated'?'已有参数档案':'框架文档引用，仓库未逐一访问')+x.frameworks.map(e=>'<small><a href="'+esc(e.url)+'" target="_blank" rel="noopener noreferrer">'+esc(e.framework)+' · '+esc(supportLabels[e.level])+' ↗</a></small>').join('')+'</td><td>'+esc(queueLabels[x.queueType])+'</td><td>'+(x.modelId?'<button class="text-button" data-detail="'+esc(x.modelId)+'">查看参数档案 ↗</button>':'<span class="unknown">待核验作者参数</span>')+'</td></tr>').join('')||'<tr><td colspan="5">此筛选中没有条目；已建档模型可切换“建档情况”查看。</td></tr>';
 $('#coverage-summary').textContent='第 '+coveragePage+' / '+pages+' 页 · 每页 50 条';$('#coverage-prev').disabled=coveragePage===1;$('#coverage-next').disabled=coveragePage===pages;
}
function renderSearchGuidance(){
 const q=normalize(state.q.trim()),box=$('#search-guidance');box.hidden=!q;if(!q)return;
 const other=models.filter(m=>normalize([m.name,m.repo,...(m.aliases||[])].join(' ')).includes(q)&&!filtered.includes(m));
 const pending=D.coverage.entries.filter(x=>!x.modelId&&normalize([x.name,x.repo,x.publisher].join(' ')).includes(q));
 const notes=[];
 if(other.length)notes.push('筛选外另有 '+other.length+' 个已建档匹配：'+other.slice(0,4).map(m=>esc(m.name)).join('、')+'。<button class="text-button" id="search-all-vendors">保留关键词，清除其他筛选 →</button>');
 if(pending.length)notes.push('覆盖清单中还有 '+pending.length+' 个匹配的待核验模型 / 变体。<button class="text-button" data-coverage-search>查看待核验条目 →</button>');
 if(!filtered.length&&!other.length&&!pending.length)notes.push('当前参数档案与覆盖清单均未匹配；可以尝试完整仓库名称，或查看覆盖检查的范围。<button class="text-button" data-view="coverage">查看覆盖检查 →</button>');
 box.hidden=!notes.length;box.innerHTML='<span class="note-mark">i</span><p>'+notes.join('<br>')+'</p>';
}

const indexState={q:'',publisher:'',engine:'',coverage:''};let indexPage=1,indexFiltered=[];
const supportLabels={recipe:'有部署示例',example:'官方表格示例',template:'官方模板选项',architecture:'架构已列',placeholder:'仅目录占位',hybrid:'混合服务架构',draft_reference:'草稿配置引用'};
function indexMatches(){return D.frameworkIndex.entries.filter(x=>{const text=[x.name,x.repo,x.vendor,x.publisher,...x.evidence.flatMap(e=>[e.framework,e.relationship,e.role,e.role==='draft'?'独立草稿':'',...(e.architectures||[])])].join(' ');return (!indexState.q||normalize(text).includes(normalize(indexState.q)))&&(!indexState.publisher||x.publisher===indexState.publisher)&&(!indexState.engine||x.evidence.some(e=>indexState.engine==='placeholder'?e.level==='placeholder':e.framework===indexState.engine))&&(!indexState.coverage||(indexState.coverage==='ready'?!!x.modelId:!x.modelId));});}
function supportCell(x,engine){const evs=x.evidence.filter(e=>e.framework===engine);if(!evs.length)return '<span class="unknown">所查表 / cookbook 未列</span>';return evs.map(e=>'<div class="index-evidence"><a href="'+esc(e.url)+'" target="_blank" rel="noopener noreferrer">'+esc(supportLabels[e.level]||e.level)+' ↗</a>'+(e.role==='draft'?'<small>独立草稿模型</small>':'')+(e.relationship==='第三方发布'?'<small>第三方发布 / 量化</small>':'')+(e.templateExpanded?'<small>模板展开，仓库未逐一核验</small>':'')+(e.architectures?'<small>'+e.architectures.map(esc).join(' / ')+'</small>':'')+(e.configUrl?'<a href="'+esc(e.configUrl)+'" target="_blank" rel="noopener noreferrer">匹配配置 ↗</a>':'')+(e.backend==='transformers'?'<small>Transformers backend</small>':'')+'</div>').join('');}
function renderFramework(){if(!$('#index-search')){$('#framework-view').innerHTML='<section class="stats framework-stats"><div><span>模型 / 变体索引</span><strong>'+D.frameworkIndex.entries.length+'</strong><small>仓库去重，含独立草稿与第三方变体</small></div><div><span>SGLang 部署文档</span><strong>'+D.frameworkIndex.sglang.pages+'</strong><small>'+D.frameworkIndex.sglang.vendors+' 个目录厂商 · 含占位页</small></div><div><span>vLLM 架构记录</span><strong>'+D.frameworkIndex.vllm.rows+'</strong><small>text + multimodal · latest 快照</small></div></section><div class="research-note"><span class="note-mark">i</span><p>只有部署示例、支持表具体示例或模板选项才构成对应级别的适配证据；<strong>目录占位、所查页面未列，均不能解释为已支持或不支持。</strong> 索引覆盖所查官方页面，参数档案需另行核验作者资料，未进行本机推理实测。<br><a href="'+D.frameworkIndex.sglang.url+'" target="_blank" rel="noopener noreferrer">SGLang 官方目录 ↗</a> · <a href="'+D.frameworkIndex.vllm.url+'" target="_blank" rel="noopener noreferrer">vLLM 官方支持表 ↗</a> · 核验 '+D.checked+'</p></div><section class="catalog-panel"><div class="search-row"><label class="search"><span>⌕</span><input id="index-search" type="search" aria-label="搜索框架索引" placeholder="查模型名称、发布账号、框架或架构…"></label><button class="button outline" id="index-csv">↓ 导出索引 CSV</button></div><div class="filters"><label>发布账号 <select id="index-publisher"><option value="">全部账号</option>'+[...new Set(D.frameworkIndex.entries.map(x=>x.publisher))].sort().map(v=>'<option>'+esc(v)+'</option>').join('')+'</select></label><label>框架 <select id="index-engine"><option value="">两份目录</option><option>SGLang</option><option>vLLM</option><option value="placeholder">仅目录占位</option></select></label><label>参数档案 <select id="index-coverage"><option value="">全部条目</option><option value="ready">已建参数档案</option><option value="pending">待建参数档案</option></select></label><span id="index-count"></span></div><div class="table-scroll" tabindex="0" aria-label="框架模型索引，可横向滚动"><table class="index-table"><thead><tr><th>具体模型 / 仓库</th><th>发布账号</th><th>SGLang 证据</th><th>vLLM 证据</th><th>参数资料</th></tr></thead><tbody id="index-rows"></tbody></table></div><div class="table-footer"><span id="index-summary"></span><div id="index-pagination"></div></div></section>';$('#index-search').addEventListener('input',e=>{indexState.q=e.target.value;indexPage=1;renderIndexRows();});for(const k of ['publisher','engine','coverage'])$('#index-'+k).addEventListener('change',e=>{indexState[k]=e.target.value;indexPage=1;renderIndexRows();});}$('#index-search').value=indexState.q;renderIndexRows();}
function renderIndexRows(){indexFiltered=indexMatches();const pages=Math.max(1,Math.ceil(indexFiltered.length/50));indexPage=Math.min(indexPage,pages);const list=indexFiltered.slice((indexPage-1)*50,indexPage*50);$('#index-count').textContent=indexFiltered.length+' 个模型 / 变体';$('#index-rows').innerHTML=list.map(x=>'<tr><td><button class="model-name" data-index-detail="'+esc(x.key)+'">'+esc(x.name)+'</button><small class="index-repo">'+esc(x.repo||'目录名称，未指定仓库')+'</small></td><td>'+esc(x.publisher)+'</td><td>'+supportCell(x,'SGLang')+'</td><td>'+supportCell(x,'vLLM')+'</td><td>'+(x.modelId?'<button class="text-button" data-detail="'+esc(x.modelId)+'">查看参数档案 ↗</button>':'<span class="unknown">待核验作者参数</span>')+'</td></tr>').join('')||'<tr><td colspan="5">未找到匹配条目。</td></tr>';$('#index-summary').textContent='第 '+indexPage+' / '+pages+' 页 · 每页 50 条';$('#index-pagination').innerHTML=(indexPage>1?'<button class="text-button" data-index-page="'+(indexPage-1)+'">← 上一页</button>':'')+(indexPage<pages?'<button class="text-button" data-index-page="'+(indexPage+1)+'">下一页 →</button>':'');}
function indexDetail(key){const x=D.frameworkIndex.entries.find(v=>v.key===key);if(!x)return;if(x.modelId){detail(x.modelId);return;}lastFocus=document.activeElement;$('#detail-content').innerHTML='<div class="detail-head"><div><div class="eyebrow">FRAMEWORK INDEX / '+esc(x.publisher)+'</div><h2 id="detail-title">'+esc(x.name)+'</h2></div><button class="close-button" id="close-detail" aria-label="关闭模型详情">×</button></div><div class="detail-body"><p class="detail-description">此条目来自框架官方目录，作者参数档案尚待核验。框架收录本身不能证明模型参数量、专家数或所有量化版本。</p>'+(x.repo?'<p><a href="https://huggingface.co/'+esc(x.repo)+'" target="_blank" rel="noopener noreferrer">文档所引仓库：'+esc(x.repo)+' ↗</a>（索引中的仓库尚未逐一访问；发布者身份见下方证据。）</p>':'')+x.evidence.map(e=>'<section class="source-evidence"><h3>'+esc(e.framework)+' · '+esc(supportLabels[e.level])+'</h3><p>'+esc(e.note)+'</p><p>'+esc(e.relationship)+' · '+(e.role==='draft'?'独立草稿模型':'目标 / 示例模型')+'</p><p>'+esc(e.locator)+'</p><a href="'+esc(e.url)+'" target="_blank" rel="noopener noreferrer">查看框架官方原页 ↗</a>'+(e.architectures?'<p>架构：'+e.architectures.map(esc).join(' / ')+'</p>':'')+'</section>').join('')+'<p>核验日期 '+D.checked+' · 未本机实测。具体软硬件条件和限制以原页为准。</p></div>';$('#detail-dialog').showModal();$('#close-detail').focus();}
function exportIndexCSV(){const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';const rows=[['模型','仓库','发布账号','参数档案','框架','证据级别','角色','发布关系','官方来源','架构匹配配置来源','定位','核验日期'],...indexFiltered.flatMap(x=>x.evidence.map(e=>[x.name,x.repo,x.publisher,x.modelId?'已建档':'待核验',e.framework,supportLabels[e.level],e.role,e.relationship,e.url,e.configUrl||'',e.locator,e.checked||D.frameworkIndex.checked]))];download('framework-index-'+D.checked+'.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('已导出当前筛选索引及官方来源。');}

function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
const saved=readLocal('model-atlas-favorites-v1',[]);
let favorites=new Set(Array.isArray(saved)?saved.filter(id=>models.some(m=>m.id===id)):[]);
const params=new URLSearchParams(location.search);
let selected=new Set((params.get('compare')||'').split(',').filter(id=>models.some(m=>m.id===id)).slice(0,4));
let view=labels[location.hash.slice(1)]?location.hash.slice(1):'catalog', sortKey='', sortDir=1, filtered=[], lastFocus=null;
const state={q:params.get('q')||'',vendor:params.get('vendor')||'',architecture:params.get('architecture')||'',precision:params.get('precision')||'',decoding:params.get('decoding')||'',access:params.get('access')||'',evidence:params.get('evidence')||'',sglang:params.get('sglang')||'',vllm:params.get('vllm')||'',favorites:params.get('favorites')==='1'};
let toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function valueText(f,key){if(!f)return '本次未核验';if(f.value===null)return f.status==='not_applicable'?'不适用':['sglang','vllm'].includes(key)?'所查页面未列':'未查得说明';const value=(key==='total'||key==='active')&&typeof f.value==='number'?f.value.toLocaleString('en-US',{maximumFractionDigits:2})+'B':String(f.value);return value+(f.status==='derived'?'（推导）':f.status==='framework'&&['total','active'].includes(key)?'（框架资料）':'');}
function fact(f,key,full=false){if(!f)return '<span class="unknown">本次未核验</span>';const classes=f.value===null?'unknown':key==='arch'?'badge '+(f.value==='Dense'?'dense':''):key==='weight'?'precision':key==='speculative'?'decode':'fact-value';const refs=f.sources.map((id,i)=>{const s=source[id];return '<a class="cite" href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer" title="'+esc(s.title+' · '+f.locator)+'" aria-label="'+esc(D.fieldDefinitions[key].label+'：'+valueText(f,key)+'，来源 '+s.title)+'">'+(full?'官方来源'+(f.sources.length>1?' '+(i+1):'')+' ↗':'↗')+'</a>';}).join('');return '<span class="fact-line '+(f.status==='derived'?'derived-mark':'')+'"><span class="'+classes+'">'+esc(valueText(f,key))+'</span>'+refs+'</span>'+(f.scope?'<small class="fact-scope">'+esc(f.scope)+'</small>':'');}
function syncUrl(){const p=new URLSearchParams();for(const k of ['q','vendor','architecture','precision','decoding','access','evidence','sglang','vllm'])if(state[k])p.set(k,state[k]);if(state.favorites)p.set('favorites','1');if(selected.size)p.set('compare',[...selected].join(','));history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+'#'+view);}
function engineMatch(m,key){const level=m.fields[key]?.supportLevel;return !state[key]||(state[key]==='exact'?['recipe','example','template'].includes(level):level===state[key]);}
function searchModels(){let list=models.filter(m=>{const hay=[m.name,m.repo,m.vendor,m.description,...(m.aliases||[]),...(m.vendor==='InternLM'||m.repo.startsWith('internlm/')?['书生']:[]),...Object.values(m.fields).map(f=>f.value??'')].join(' ').toLowerCase();return (!state.q||normalize(hay).includes(normalize(state.q.trim())))&&(!state.vendor||m.vendor===state.vendor)&&(!state.architecture||(state.architecture==='unknown'?m.fields.arch.value===null:(state.architecture==='MoE'?String(m.fields.arch.value||'').includes('MoE'):m.fields.arch.value===state.architecture)))&&(!state.precision||[m.fields.weight.value,m.fields.quantization.value].join(' ').includes(state.precision))&&(!state.decoding||(state.decoding==='unknown'?m.fields.speculative.status==='not_found':(state.decoding==='MTP'?String(m.fields.speculative.value||'').includes('MTP')&&m.fields.speculative.value!=='原生 MTP 层数 0':String(m.fields.speculative.value||'').includes(state.decoding))))&&(!state.access||m.access===state.access)&&(!state.evidence||(state.evidence==='derived'?Object.values(m.fields).some(f=>f.status==='derived'):!Object.values(m.fields).some(f=>f.status==='derived')))&&engineMatch(m,'sglang')&&engineMatch(m,'vllm')&&(!state.favorites||favorites.has(m.id));});if(sortKey)list.sort((a,b)=>{let x=typeof a.fields[sortKey].value==='number'?a.fields[sortKey].value:null,y=typeof b.fields[sortKey].value==='number'?b.fields[sortKey].value:null;if(x===null&&y===null)return 0;if(x===null)return 1;if(y===null)return -1;return (x-y)*sortDir;});return list;}
function renderCatalog(){filtered=searchModels();renderSearchGuidance();$('#result-count').textContent=filtered.length+' 个版本';$('#model-rows').innerHTML=filtered.map(m=>'<tr><td><input type="checkbox" data-select="'+m.id+'" aria-label="将 '+esc(m.name)+' 加入对比" '+(selected.has(m.id)?'checked':'')+'></td><td><button class="model-name" data-detail="'+m.id+'"><i class="model-tag" data-vendor="'+m.vendor+'"></i>'+esc(m.name)+'</button><a class="vendor-name" href="'+esc(source[m.card].url)+'" target="_blank" rel="noopener noreferrer">'+esc(m.vendor)+(m.access==='api'?' · API 服务 ↗':' · 官方模型卡 ↗')+'</a></td>'+['arch','total','active','routed','selected','weight','speculative','sglang','vllm'].map(k=>'<td>'+fact(m.fields[k],k)+'</td>').join('')+'<td><button class="star '+(favorites.has(m.id)?'saved':'')+'" data-favorite="'+m.id+'" aria-pressed="'+favorites.has(m.id)+'" aria-label="'+(favorites.has(m.id)?'取消收藏 ':'收藏 ')+esc(m.name)+'">'+(favorites.has(m.id)?'★':'☆')+'</button></td></tr>').join('');$('#empty').hidden=filtered.length>0;$('#table-summary').textContent='显示 '+filtered.length+' / '+models.length+' 款模型';$('#model-table').hidden=filtered.length===0;document.querySelectorAll('[data-sort]').forEach(b=>{b.querySelector('span').textContent=b.dataset.sort===sortKey?(sortDir===1?'↑':'↓'):'↕';b.closest('th').setAttribute('aria-sort',b.dataset.sort===sortKey?(sortDir===1?'ascending':'descending'):'none');});}
function updateTray(){$('#compare-count').textContent=selected.size;$('#selected-count').textContent=selected.size;$('#selected-names').textContent=models.filter(m=>selected.has(m.id)).map(m=>m.name).join(' / ');$('#compare-tray').hidden=!selected.size||view==='compare';}
function renderCompare(){const list=models.filter(m=>selected.has(m.id));if(!list.length){$('#compare-view').innerHTML='<div class="compare-empty"><span>⇄</span><h2>先挑选你想了解的模型</h2><p>在模型目录勾选 2–4 款模型，即可逐项查看差异与出处。</p><button data-view="catalog" class="button">去模型目录挑选 →</button></div>';return;}
$('#compare-view').innerHTML='<div class="compare-toolbar"><span>已选 '+list.length+' / 4 款 · 可返回目录继续添加</span><button class="text-button" data-view="catalog">＋ 添加模型</button></div><div class="compare-wrap"><table class="compare-table"><colgroup><col style="width:150px">'+list.map(()=>'<col>').join('')+'</colgroup><thead><tr><th>字段 / 官方来源</th>'+list.map(m=>'<td><span class="vendor-name">'+m.vendor+'</span><h3><button class="model-name" data-detail="'+m.id+'">'+esc(m.name)+'</button></h3><button class="remove" data-remove="'+m.id+'">移出对比 ×</button></td>').join('')+'</tr></thead><tbody>'+Object.entries(D.fieldDefinitions).map(([key,def])=>'<tr><td>'+esc(def.label)+'</td>'+list.map(m=>'<td>'+fact(m.fields[key],key)+'<p>'+esc(m.fields[key]?.note||'')+'</p></td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="research-note"><span class="note-mark">i</span><p>对比用于核对技术规格，不作为模型能力排名。数字只在口径一致时可直接比较。</p></div>';}
function renderSources(){const groups=[...new Set(Object.values(source).map(s=>s.vendor))];$('#sources-view').innerHTML='<p class="source-summary">共 '+Object.keys(source).length+' 条参数档案引用的官方资料；全量模型引用与链接另见框架支持索引。包括模型作者资料与 SGLang / vLLM 官方文档；框架目录仅为支持证据，不能作为作者参数披露；每项事实在模型详情中注明原文位置。核验日期：'+D.checked+'。</p>'+groups.map(v=>'<section class="source-group"><header><h2>'+esc(v)+'</h2><span>'+Object.values(source).filter(s=>s.vendor===v).length+' SOURCES</span></header>'+Object.values(source).filter(s=>s.vendor===v).map(s=>{const uses=models.reduce((n,m)=>n+Object.values(m.fields).filter(f=>f.sources.includes(s.id)).length,0);return '<div class="source-entry"><div><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+' ↗</a><p>'+esc(s.kind)+' · '+uses+' 项字段引用 · '+(/^[a-f0-9]{40}$/.test(s.revision)?'固定提交 '+s.revision.slice(0,8):'在线来源')+'</p><small>'+esc(s.url)+'</small></div><small>核验 '+s.checked+'</small></div>';}).join('')+'</section>').join('');}
function renderGuide(){$('#guide-view').innerHTML='<div class="prose"><section class="prose-section"><h2>收录标准</h2><p>当前收录 '+models.length+' 个开放权重版本与 API 服务，以开发方官方模型卡、配置和技术报告为依据。精确记录仓库名称，不把同系列不同版本的信息拼接成一个模型。部分新模型卡与配置固定到核验时的提交；其余在线页面和 main 分支来源仍需复查是否变化。API 服务不假设与相近名称的开放权重模型等同。</p><p>资料快照核验于 <strong>'+D.checked+'</strong>。这是人工维护的资料库，不是实时爬取的模型榜单；没有宣称覆盖所有常用模型、所有最新版本或全部量化格式。</p></section><section class="prose-section"><h2>框架索引的范围</h2><p>参数档案共 '+models.length+' 个；框架索引另收录 '+D.frameworkIndex.entries.length+' 个模型或变体引用，来自 SGLang 的 '+D.frameworkIndex.sglang.pages+' 篇 cookbook 和 vLLM 的 '+D.frameworkIndex.vllm.rows+' 行支持架构。索引中尚未核验作者参数的条目会明确显示待建档，不把收录索引计成参数齐全。独立草稿、第三方量化、模板选项与目录占位分别保留。</p><p>vLLM 来源为 latest 文档，页面更新时间 '+D.frameworkIndex.vllm.pageUpdated+'，并非所有已发布软件版本均支持。只列出架构时不能当作具体检查点、量化、MTP 和特定硬件均可用；目录未列出也不等于不支持。</p></section><section class="prose-section"><h2>字段字典</h2><dl>'+Object.values(D.fieldDefinitions).map(def=>'<dt>'+esc(def.label)+'</dt><dd>'+esc(def.description)+'</dd>').join('')+'</dl></section><section class="prose-section"><h2>证据状态怎么读</h2><dl><dt>官方明示</dt><dd>开发方的模型卡或报告直接给出。点击字段后的 ↗ 可回到原文。</dd><dt>框架官方文档</dt><dd>SGLang / vLLM 官方页面直接声明的模型信息或适配示例。与模型作者披露分开标记；支持示例只覆盖原页列出的版本、硬件和功能条件，未在本项目运行实测。</dd><dt>官方配置</dt><dd>从 config.json 等官方配置读取。配置声明不能单独证明对应权重已发布、框架已实现或某项性能已实测。</dd><dt>官方关系推导</dt><dd>只有官方明确声明同结构、同检查点附加模块，或明确披露组成部分时才推导。每项保留前提、来源链与适用范围。主模型参数不能冒充含草稿模块的完整检查点总量；不以总量乘专家比例估算激活参数。</dd><dt>未查得说明</dt><dd>在本次已查阅的官方资料中未找到明确证据。它不等于厂商从未披露，也不等于模型不支持。</dd><dt>不适用</dt><dd>字段不适合该架构，例如 Dense 模型的 MoE 路由专家数量。</dd></dl></section><section class="prose-section"><h2>如何维护与使用</h2><p>编辑本项目 data/ 中的数据源，再生成网站数据；贡献与定时维护流程见 GitHub 项目说明。每次更新都应重新打开官方资料，记录准确仓库版本、字段位置和核验日期；不能只修改日期冒充重新核验。</p><p>框架页的“导出数据”导出完整索引，索引CSV导出当前筛选。模型页“导出数据”导出当前筛选结果（对比页导出已选模型），包含逐字段来源、证据状态和日期。“导出 CSV”便于放入表格，每个字段都有独立的来源列。收藏仅保存在当前浏览器；筛选与对比选择保存在网址中。</p></section></div>';}
function setView(next,update=true){if(!labels[next])return;view=next;const [crumb,title,sub]=labels[next];$('#crumb').textContent=crumb;$('#page-title').textContent=title;$('#page-subtitle').textContent=sub;for(const k of Object.keys(labels))$('#'+k+'-view').hidden=k!==view;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='compare')renderCompare();if(view==='framework')renderFramework();if(view==='coverage')renderCoverage();if(view==='sources')renderSources();if(view==='guide')renderGuide();updateTray();if(update)syncUrl();}
function toggleSelection(id,remove=false){if(selected.has(id)||remove)selected.delete(id);else if(selected.size<4)selected.add(id);else toast('最多对比 4 款模型，请先移出一款。');renderCatalog();updateTray();if(view==='compare')renderCompare();syncUrl();}
function detail(id){const m=models.find(m=>m.id===id);if(!m)return;lastFocus=document.activeElement;
const statusNames={verified:'官方明示',config:'官方配置',framework:'框架官方文档',derived:'官方关系推导',not_found:'未查得说明',not_applicable:'不适用'};
$('#detail-content').innerHTML='<div class="detail-head"><div><div class="eyebrow">MODEL DOSSIER / '+esc(m.vendor.toUpperCase())+'</div><h2 id="detail-title">'+esc(m.name)+'</h2><a href="'+esc(source[m.card].url)+'" target="_blank" rel="noopener noreferrer" class="vendor-name">'+(m.access==='api'?'官方服务标识 ':'官方仓库 ')+esc(m.repo)+' ↗</a></div><button class="close-button" id="close-detail" aria-label="关闭模型详情">×</button></div><div class="detail-body"><p class="detail-description">'+esc(m.description)+' 最近字段核验：'+m.checked+'；各字段日期见证据位置。</p><div class="facts-grid">'+Object.entries(D.fieldDefinitions).filter(([k])=>m.fields[k]).map(([key,def])=>{const f=m.fields[key];return '<div class="fact-card"><small>'+esc(def.label)+'<span class="status-label">'+statusNames[f.status]+'</span></small>'+fact(f,key,true)+(f.note?'<p>'+esc(f.note)+'</p>':'')+(f.derivation?'<ol class="derivation-list">'+f.derivation.premises.map(step=>'<li>'+esc(step)+'</li>').join('')+'</ol><p class="derivation-limit">'+esc(f.derivation.limitation)+'</p>':'')+'</div>';}).join('')+'</div><section class="source-evidence"><h3>证据位置与原始资料</h3>'+Object.entries(m.fields).map(([key,f])=>'<div class="evidence-row"><strong>'+esc(D.fieldDefinitions[key].label)+' · '+esc(f.locator)+'</strong>'+f.sources.map(id=>'<a href="'+esc(source[id].url)+'" target="_blank" rel="noopener noreferrer">'+esc(source[id].title)+' ↗</a>').join('')+'<p>核验 '+f.checked+' · '+esc(statusNames[f.status])+' · 来源版本见官方来源索引</p></div>').join('')+'</section><div class="detail-actions"><button class="button" data-detail-compare="'+m.id+'">'+(selected.has(m.id)?'移出对比':'＋ 加入对比')+'</button><button class="button outline" data-copy-model="'+m.id+'">复制模型资料</button></div></div>';
$('#detail-dialog').showModal();$('#close-detail').focus();}
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportJSON(){if(view==='coverage'){download('coverage-audit-'+D.coverage.checkedAt.slice(0,10)+'.json',JSON.stringify(D.coverage,null,2),'application/json;charset=utf-8');return;}if(view==='framework'){download('framework-index-'+D.checked+'.json',JSON.stringify(D.frameworkIndex,null,2),'application/json;charset=utf-8');toast('已导出完整框架索引及来源。');return;}const list=view==='compare'?models.filter(m=>selected.has(m.id)):filtered;if(!list.length){toast('当前没有可导出的模型。');return;}const used=new Set(list.flatMap(m=>Object.values(m.fields).flatMap(f=>f.sources)).concat(list.flatMap(m=>[m.card,m.config])));download('model-atlas-'+D.checked+'.json',JSON.stringify({...D,frameworkIndex:undefined,coverage:undefined,models:list,sources:Object.fromEntries(Object.entries(source).filter(([id])=>used.has(id)))},null,2),'application/json;charset=utf-8');toast('已导出 '+list.length+' 款模型及逐项来源。');}
function exportCSV(){if(!filtered.length){toast('没有可导出的结果。');return;}const fields=Object.entries(D.fieldDefinitions);const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';const header=['模型','厂商','仓库','核验日期',...fields.flatMap(([key,d])=>[d.label,d.label+' · 官方来源',d.label+' · 原文位置',d.label+' · 状态',d.label+' · 口径说明'])];const rows=filtered.map(m=>[m.name,m.vendor,source[m.card].url,m.checked,...fields.flatMap(([key])=>{const f=m.fields[key];return [valueText(f,key),(f?.sources||[]).map(id=>source[id].url).join(' ; '),f?.locator||'',f?.status||'not_reviewed',[f?.scope,f?.note,...(f?.derivation?.premises||[])].filter(Boolean).join('；')];})]);download('model-atlas-'+D.checked+'.csv','\uFEFF'+[header,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('已导出 '+filtered.length+' 款模型的 CSV。');}
function reset() {Object.assign(state,{q:'',vendor:'',architecture:'',precision:'',decoding:'',access:'',evidence:'',sglang:'',vllm:'',favorites:false});sortKey='';bindInputs();renderCatalog();syncUrl();}
function bindInputs(){$('#search').value=state.q;for(const k of ['vendor','architecture','precision','decoding','access','evidence','sglang','vllm']){$('#'+k).value=state[k];if($('#'+k).value!==state[k])state[k]='';}$('#favorites-only').checked=state.favorites;}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){setView(b.dataset.view);return;}if(b.dataset.indexDetail){indexDetail(b.dataset.indexDetail);return;}if(b.dataset.indexPage){indexPage=Number(b.dataset.indexPage);renderIndexRows();return;}if(b.id==='index-csv'){exportIndexCSV();return;}if(b.dataset.coverageSearch!==undefined){coverageState.q=state.q;setView('coverage');return;}if(b.id==='search-all-vendors'){for(const k of ['vendor','architecture','precision','decoding','access','evidence','sglang','vllm'])state[k]='';state.favorites=false;bindInputs();renderCatalog();syncUrl();return;}if(b.id==='coverage-prev'||b.id==='coverage-next'){coveragePage+=b.id==='coverage-prev'?-1:1;renderCoverageRows();return;}if(b.dataset.indexSearch!==undefined){indexState.q=state.q;setView('framework');return;}if(b.dataset.detail){detail(b.dataset.detail);return;}if(b.dataset.favorite){const id=b.dataset.favorite;favorites.has(id)?favorites.delete(id):favorites.add(id);try{localStorage.setItem('model-atlas-favorites-v1',JSON.stringify([...favorites]));}catch{toast('浏览器未允许保存收藏，当前会话仍可使用。');}renderCatalog();return;}if(b.dataset.remove){toggleSelection(b.dataset.remove,true);return;}if(b.dataset.sort){if(sortKey===b.dataset.sort)sortDir*=-1;else{sortKey=b.dataset.sort;sortDir=1;}renderCatalog();return;}if(b.dataset.detailCompare){const id=b.dataset.detailCompare;toggleSelection(id);b.textContent=selected.has(id)?'移出对比':'＋ 加入对比';return;}if(b.dataset.copyModel){const m=models.find(m=>m.id===b.dataset.copyModel);const text=['# '+m.name,'官方发布：'+source[m.card].url,'核验日期：'+m.checked,'',...Object.entries(m.fields).map(([k,f])=>D.fieldDefinitions[k].label+'：'+valueText(f,k)+'\n'+f.sources.map(id=>source[id].url).join('\n')+'\n位置：'+f.locator+(f.note?'\n说明：'+f.note:''))].join('\n');try{await navigator.clipboard.writeText(text);toast('已复制资料与来源。');}catch{download(m.id+'.txt',text,'text/plain;charset=utf-8');toast('已下载模型资料文本。');}return;}switch(b.id){case 'close-detail':$('#detail-dialog').close();break;case 'export-json':exportJSON();break;case 'csv-export':exportCSV();break;case 'reset':case 'empty-reset':reset();break;case 'clear-compare':selected.clear();renderCatalog();updateTray();syncUrl();break;}});
document.addEventListener('change',e=>{if(e.target.dataset.select){toggleSelection(e.target.dataset.select);return;}if(['vendor','architecture','precision','decoding','access','evidence','sglang','vllm'].includes(e.target.id)){state[e.target.id]=e.target.value;renderCatalog();syncUrl();}if(e.target.id==='favorites-only'){state.favorites=e.target.checked;renderCatalog();syncUrl();}});
$('#search').addEventListener('input',e=>{state.q=e.target.value;renderCatalog();syncUrl();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#detail-dialog').open){e.preventDefault();setView('catalog');$('#search').focus();}});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#detail-dialog').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
window.addEventListener('hashchange',()=>setView(location.hash.slice(1),false));
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);for(const k of ['q','vendor','architecture','precision','decoding','access','evidence','sglang','vllm'])state[k]=p.get(k)||'';state.favorites=p.get('favorites')==='1';selected=new Set((p.get('compare')||'').split(',').filter(id=>models.some(m=>m.id===id)).slice(0,4));bindInputs();renderCatalog();setView(labels[location.hash.slice(1)]?location.hash.slice(1):'catalog',false);});
$('#vendor').innerHTML+=[...new Set(models.map(m=>m.vendor))].sort().map(v=>'<option>'+v+'</option>').join('');
$('#coverage-nav-count').textContent=D.coverage.entries.filter(x=>!x.modelId).length;$('#framework-nav-count').textContent=D.frameworkIndex.entries.length;document.querySelector('.sidebar-bottom small').textContent='事实快照 · '+D.checked;document.querySelector('.stat-update strong').innerHTML=D.checked.slice(5).replace('-','.')+'<em>'+D.checked.slice(0,4)+'</em>';document.querySelector('.footer>span:last-child').textContent='事实快照 '+D.checked+' · v0.1';$('#nav-count').textContent=models.length;$('#stat-models').textContent=models.length.toString().padStart(2,'0');$('#stat-vendors').textContent=new Set(models.map(m=>m.vendor)).size.toString().padStart(2,'0');$('#stat-facts').textContent=models.reduce((n,m)=>n+Object.values(m.fields).filter(f=>f.value!==null).length,0);
if(D.project?.repository){const url='https://github.com/'+D.project.repository;$('#project-links').innerHTML='<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">GitHub ↗</a> · <a href="'+esc(url+'/issues')+'" target="_blank" rel="noopener noreferrer">纠错 / 补充 ↗</a>';}
bindInputs();renderCatalog();setView(view,false);
})();
